set events {}
proc record {name element operation} {lappend ::events $name}
proc p {} {
    trace variable ::errorInfo w record
    trace variable result w record
    set ::events {}
    catch {expr {1/0}} result
    trace vdelete ::errorInfo w record
    trace vdelete result w record
    return $::events
}
puts [p]

